/**
 * Sweep harness: provision one throwaway game server for <family> on node-2.
 * Usage: npx tsx provision.ts <family>
 * Prints a single JSON line with { serverId, hostname, family, planId }.
 */
import { db } from "/opt/nxeon/lib/db";

const NODE2 = "cmto2zpwh0000hltqk6oaxy69";
const OPS_USER = "cmrztujaw0002hlazl58i3lsi";

(async () => {
  const family = process.argv[2];
  if (!family) throw new Error("usage: provision.ts <family>");

  const gamePlan = await db.gamePlan.findFirst({
    where: { gameFamily: family },
    orderBy: { priceCents: "asc" },
  });
  if (!gamePlan) {
    console.log(JSON.stringify({ family, skip: "no-gameplan" }));
    await db.$disconnect();
    return;
  }

  // hostname: /^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i and <= 40 chars
  const stamp = Date.now().toString(36);
  const hostname = `t-${family.replace(/[^a-z0-9]/gi, "")}-${stamp}`.slice(0, 40).replace(/-$/, "");

  const server = await db.server.create({
    data: {
      name: hostname,
      hostname,
      userId: OPS_USER,
      planId: gamePlan.basePlanId,
      osTemplateId: gamePlan.osTemplateId,
      gamePlanId: gamePlan.id,
      nodeId: NODE2,
      isFree: true,
      termPromoPercent: 100,
    },
  });
  await db.job.create({ data: { type: "PROVISION", serverId: server.id } });

  console.log(
    JSON.stringify({
      serverId: server.id,
      hostname,
      family,
      planId: gamePlan.id,
      planName: gamePlan.name,
    })
  );
  await db.$disconnect();
})().catch((e) => {
  console.error(e);
  process.exit(1);
});
=============== wait.sh
#!/usr/bin/env bash
# Poll a PROVISION job until it reaches DONE or FAILED (or the deadline).
# Usage: wait.sh <serverId> [maxSeconds]
set -u
SW=/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/sweep
SID="$1"
MAX="${2:-1800}"
cd /opt/nxeon
START=$(date +%s)
LAST=""
until false; do
  OUT=$(npx tsx "$SW/status.ts" "$SID" 2>&1)
  ST=$(printf '%s' "$OUT" | python3 -c 'import sys,json;d=json.load(sys.stdin);print((d.get("job") or {}).get("status",""))' 2>/dev/null)
  STEP=$(printf '%s' "$OUT" | python3 -c 'import sys,json;d=json.load(sys.stdin);print((d.get("server") or {}).get("provisioningStep") or "")' 2>/dev/null)
  NOW=$(date +%s); EL=$((NOW-START))
  if [ "$ST$STEP" != "$LAST" ]; then
    echo "[${EL}s] job=$ST step=$STEP"
    LAST="$ST$STEP"
  fi
  case "$ST" in
    DONE|FAILED) echo "FINAL after ${EL}s:"; printf '%s\n' "$OUT"; exit 0 ;;
  esac
  if [ "$EL" -ge "$MAX" ]; then echo "TIMEOUT after ${EL}s:"; printf '%s\n' "$OUT"; exit 2; fi
  sleep 5
done
=============== verify.sh
#!/usr/bin/env bash
# Standard in-guest health probe for a sweep test server.
# Usage: verify.sh <serverId> <sshPort>
#
# 2026-09-06 (2nd pass): also collects the two things the first 10 families kept
# having to be re-SSHed for — root-fs headroom (the CS2/Project Zomboid disk
# class of bug) and bind-mount ownership vs the container's own uid (the CS2
# "container writes into its own layer, a docker rm destroys the customer's
# server" class of bug) — plus a tail of the game container's log, which is what
# actually distinguishes "still installing" from "dead on a prompt".
set -u
SW=/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/sweep
SID="$1"; SPORT="$2"
bash "$SW/connect.sh" "$SID" 178.63.94.114 "$SPORT" '
echo "SSH_OK $(hostname) uptime:$(cut -d. -f1 /proc/uptime)s"
echo "--- docker ps ---"
docker ps --format "{{.Names}} | {{.Image}} | {{.Status}} | {{.Ports}}" 2>&1 | head -10
echo "--- docker ps -a (non-running) ---"
docker ps -a --filter status=exited --filter status=created --filter status=restarting --format "{{.Names}} | {{.Status}}" 2>&1 | head -10
echo "--- listening tcp ---"
ss -tlnp 2>/dev/null | grep -v "127.0.0" | tail -n +2
echo "--- listening udp ---"
ss -ulnp 2>/dev/null | grep -v "127.0.0" | tail -n +2
echo "--- game systemd units ---"
systemctl list-units --type=service --state=running --plain --no-legend 2>/dev/null | grep -viE "systemd|dbus|cron|ssh|networkd|resolved|udev|journal|getty|rsyslog|polkit|unattended|qemu|snapd|multipath|irqbalance|chrony|uuidd|packagekit|apport|nxeon-node" | head -10
echo "--- disk ---"
df -h / | tail -1
echo "--- bind mount ownership + size (host side) ---"
for d in /opt/*/; do case "$d" in /opt/nxeon*) continue;; esac; printf "%s " "$(stat -c "%n %U:%G %a" "$d" 2>/dev/null)"; du -sh "$d" 2>/dev/null | cut -f1; done
echo "--- container uid ---"
for c in $(docker ps --format "{{.Names}}"); do echo "$c: $(docker exec "$c" id 2>&1 | head -1)"; done
echo "--- container log (tail) ---"
for c in $(docker ps --format "{{.Names}}"); do echo "== $c =="; docker logs --tail 12 "$c" 2>&1 | tail -12; done
'
=============== info.ts
/**
 * Sweep harness: dump a test server's connection details + port forwards.
 * Writes the root password to <scratch>/pw-<serverId> (mode 600) and prints
 * everything else as JSON — the password is NEVER printed.
 * Usage: npx tsx info.ts <serverId>
 */
import { db } from "/opt/nxeon/lib/db";
import { decryptSecret } from "/opt/nxeon/lib/crypto-box";
import { GAME_PORT, type GameFamily } from "/opt/nxeon/lib/games";
import { writeFileSync, chmodSync } from "node:fs";

const SCRATCH = "/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/sweep";

(async () => {
  const serverId = process.argv[2];
  if (!serverId) throw new Error("usage: info.ts <serverId>");
  const s = await db.server.findUnique({
    where: { id: serverId },
    select: {
      id: true,
      hostname: true,
      status: true,
      vmid: true,
      ipAddress: true,
      sshPort: true,
      rootPassword: true,
      rootPasswordEnc: true,
      gameVariant: true,
      gameConfig: true,
      dedicatedIp: { select: { address: true } },
      node: { select: { publicIp: true, name: true, pveNode: true, isPrimary: true } },
      gamePlan: { select: { gameFamily: true, name: true } },
      osTemplate: { select: { family: true, name: true } },
      plan: { select: { ramMB: true, cpuCores: true, diskGB: true } },
    },
  });
  if (!s) throw new Error(`server ${serverId} not found`);

  const pw = s.rootPassword ?? decryptSecret(s.rootPasswordEnc);
  const pwFile = `${SCRATCH}/pw-${serverId}`;
  if (pw) {
    writeFileSync(pwFile, pw, "utf8");
    chmodSync(pwFile, 0o600);
  }

  const family = (s.gamePlan?.gameFamily ?? s.osTemplate?.family) as GameFamily | undefined;
  const gp = family ? GAME_PORT[family] : undefined;

  const forwards = await db.portForward.findMany({
    where: { serverId },
    select: { id: true, publicPort: true, guestPort: true, protocol: true },
    orderBy: { guestPort: "asc" },
  });

  console.log(
    JSON.stringify(
      {
        id: s.id,
        hostname: s.hostname,
        status: s.status,
        vmid: s.vmid,
        privateIp: s.ipAddress,
        sshPort: s.sshPort,
        dedicatedIp: s.dedicatedIp?.address ?? null,
        node: s.node,
        family,
        gamePlan: s.gamePlan?.name,
        plan: s.plan,
        gamePort: gp,
        gameVariant: s.gameVariant,
        gameConfig: s.gameConfig,
        forwards,
        pwFile: pw ? pwFile : null,
        gamePortForward: gp ? forwards.find((f) => f.guestPort === gp.port && f.protocol === gp.protocol) ?? null : null,
      },
      null,
      2
    )
  );
  await db.$disconnect();
})().catch((e) => {
  console.error(e);
  process.exit(1);
});
=============== udpcheck.sh
#!/usr/bin/env bash
# Prove a UDP game port is reachable END TO END: send raw UDP from THIS box to the
# node's public IP:publicPort and confirm (a) the node's DNAT rule counter moved and
# (b) tcpdump INSIDE the guest saw the packets on the guest port.
# Usage: udpcheck.sh <serverId> <sshHost=nodePublicIp> <sshPort> <publicPort> <guestPort>
set -u
SW=/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/sweep
SID="$1"; HOST="$2"; SPORT="$3"; PUBPORT="$4"; GPORT="$5"
CAP="$SW/cap-$SID.txt"

# NAT counter before
echo "=== node DNAT rule (before) ==="
ssh -o StrictHostKeyChecking=no -o ConnectTimeout=15 "root@$HOST" \
  "iptables -t nat -L NXEON_FWD_N2 -n -v --line-numbers 2>/dev/null | grep -E 'dpt:$PUBPORT( |\$)' || echo '(no rule found for dpt:$PUBPORT)'"

# tcpdump inside the guest, in the background locally
( bash "$SW/connect.sh" "$SID" "$HOST" "$SPORT" \
    "command -v tcpdump >/dev/null 2>&1 || (apt-get install -y -qq tcpdump >/dev/null 2>&1); timeout 20 tcpdump -ni any -c 4 udp port $GPORT 2>&1" \
    > "$CAP" 2>&1 ) &
CAPPID=$!

sleep 6
echo "=== sending UDP probes to $HOST:$PUBPORT ==="
for i in 1 2 3 4 5 6; do
  printf 'nxeon-reachability-probe' | timeout 2 nc -u -w1 "$HOST" "$PUBPORT" >/dev/null 2>&1
  sleep 1
done

wait $CAPPID 2>/dev/null
echo "=== tcpdump inside the guest (port $GPORT) ==="
cat "$CAP"

echo "=== node DNAT rule (after) ==="
ssh -o StrictHostKeyChecking=no -o ConnectTimeout=15 "root@$HOST" \
  "iptables -t nat -L NXEON_FWD_N2 -n -v --line-numbers 2>/dev/null | grep -E 'dpt:$PUBPORT( |\$)' || echo '(no rule found for dpt:$PUBPORT)'"
=============== teardown-db.ts
/**
 * Sweep harness: delete a throwaway test server's DB rows COMPLETELY.
 * Refuses to touch anything that isn't one of this sweep's own servers
 * (ops user + hostname prefix "t-"), so it can never hit a real customer row.
 * Usage: npx tsx teardown-db.ts <serverId>
 */
import { db } from "/opt/nxeon/lib/db";

const OPS_USER = "cmrztujaw0002hlazl58i3lsi";

(async () => {
  const serverId = process.argv[2];
  if (!serverId) throw new Error("usage: teardown-db.ts <serverId>");
  const s = await db.server.findUnique({
    where: { id: serverId },
    select: { id: true, hostname: true, userId: true, vmid: true, nodeId: true },
  });
  if (!s) {
    console.log(JSON.stringify({ serverId, result: "already-gone" }));
    await db.$disconnect();
    return;
  }
  // Hard safety gate — this sweep only ever created rows shaped like this.
  if (s.userId !== OPS_USER || !/^t-[a-z0-9]+-[a-z0-9]+$/.test(s.hostname)) {
    throw new Error(
      `REFUSING to delete ${s.id} (${s.hostname}): not a sweep-created throwaway server`
    );
  }

  const pf = await db.portForward.deleteMany({ where: { serverId } });
  const jobs = await db.job.deleteMany({ where: { serverId } });
  // Anything else that could hold an FK to Server — delete defensively but only
  // for this row. Unknown models are skipped silently.
  for (const model of [
    "backup",
    "serverMetric",
    "gameSchedule",
    "notification",
  ] as const) {
    try {
      // @ts-expect-error dynamic model access, guarded by try/catch
      await db[model].deleteMany({ where: { serverId } });
    } catch {
      /* model doesn't exist or has no serverId — fine */
    }
  }
  await db.server.delete({ where: { id: serverId } });
  console.log(
    JSON.stringify({ serverId, hostname: s.hostname, vmid: s.vmid, deletedForwards: pf.count, deletedJobs: jobs.count, result: "deleted" })
  );
  await db.$disconnect();
})().catch((e) => {
  console.error(String(e?.message ?? e));
  process.exit(1);
});
