/**
 * Sweep harness: one-shot job/server status probe. Usage: npx tsx status.ts <serverId>
 * Prints one JSON line. Designed to be called from an `until` bash loop.
 */
import { db } from "/opt/nxeon/lib/db";

(async () => {
  const serverId = process.argv[2];
  if (!serverId) throw new Error("usage: status.ts <serverId>");
  const job = await db.job.findFirst({
    where: { serverId, type: "PROVISION" },
    orderBy: { createdAt: "desc" },
    select: { id: true, status: true, attempts: true, error: true, createdAt: true, updatedAt: true },
  });
  const server = await db.server.findUnique({
    where: { id: serverId },
    select: { status: true, vmid: true, ipAddress: true, sshPort: true, provisioningStep: true, provisionError: true },
  });
  console.log(JSON.stringify({ job, server }));
  await db.$disconnect();
})().catch((e) => {
  console.error(e);
  process.exit(1);
});
