#!/usr/bin/env bash
# Print the ports a container is really LISTENING on, by protocol, read from its
# own netns /proc/net (works even when the image has no ss/netstat).
# Usage: ctports.sh <serverId> <sshPort> <containerName>
set -u
SW=/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/sweep
bash "$SW/connect.sh" "$1" 178.63.94.114 "$2" "
PID=\$(docker inspect -f '{{.State.Pid}}' $3 2>/dev/null)
[ -z \"\$PID\" ] || [ \"\$PID\" = 0 ] && { echo 'container not running'; exit 0; }
echo -n 'TCP listen: '
awk 'NR>1 && \$4==\"0A\"{split(\$2,a,\":\"); print strtonum(\"0x\" a[2])}' /proc/\$PID/net/tcp /proc/\$PID/net/tcp6 2>/dev/null | sort -un | tr '\n' ' '
echo
echo -n 'UDP bound:  '
awk 'NR>1{split(\$2,a,\":\"); print strtonum(\"0x\" a[2])}' /proc/\$PID/net/udp /proc/\$PID/net/udp6 2>/dev/null | sort -un | tr '\n' ' '
echo
"

import { db } from "/opt/nxeon/lib/db";
const OPS_USER = "cmrztujaw0002hlazl58i3lsi";
(async () => {
  const servers = await db.server.findMany({
    where: { OR: [{ userId: OPS_USER }, { hostname: { startsWith: "t-" } }] },
    select: { id: true, hostname: true, status: true, vmid: true, userId: true, createdAt: true },
    orderBy: { createdAt: "desc" },
  });
  console.log("=== sweep-shaped servers (ops user or t- prefix) ===");
  for (const s of servers) console.log(`${s.id} ${s.hostname} status=${s.status} vmid=${s.vmid} created=${s.createdAt.toISOString()}`);
  // orphaned jobs/forwards pointing to servers that no longer exist
  const allServerIds = new Set((await db.server.findMany({ select: { id: true } })).map(s => s.id));
  const jobs = await db.job.findMany({ where: { type: "PROVISION" }, select: { id: true, serverId: true, status: true } });
  const orphanJobs = jobs.filter(j => j.serverId && !allServerIds.has(j.serverId));
  console.log(`\n=== orphan PROVISION jobs (serverId not in Server table): ${orphanJobs.length} ===`);
  for (const j of orphanJobs) console.log(`${j.id} serverId=${j.serverId} status=${j.status}`);
  const pfs = await db.portForward.findMany({ select: { id: true, serverId: true, publicPort: true, guestPort: true } });
  const orphanPf = pfs.filter(p => !allServerIds.has(p.serverId));
  console.log(`\n=== orphan PortForward rows: ${orphanPf.length} ===`);
  for (const p of orphanPf) console.log(`${p.id} serverId=${p.serverId} ${p.guestPort}->${p.publicPort}`);
  await db.$disconnect();
})().catch(e => { console.error(e); process.exit(1); });
