test("joinPortFor resolves a well-formed entry for every family", () => {
  for (const fam of GAME_FAMILIES) {
    const entry = joinPortFor(fam);
    assert.ok(entry, `missing join port for ${fam}`);
    assert.ok(Number.isInteger(entry.port), `${fam} join port is not an integer`);
    assert.ok(entry.port > 0 && entry.port < 65536, `${fam} join port ${entry.port} out of range`);
    assert.ok(entry.protocol === "tcp" || entry.protocol === "udp", `${fam} join protocol invalid`);
  }
});

