/* ------------------------------------------------------------------ *
 * gameUnitCrashLooping: is the game dead rather than slow?
 * Guards the 2026-09-07 fix — a crash-looping container logs continuously, so
 * `installProgressed` read it as work forever and a broken family burned the
 * full 45-minute ceiling on each of its three attempts (~2.25 hours of
 * "Installing the game…") before failing. Seen on Eco, Garry's Mod, The Forest.
 * ------------------------------------------------------------------ */

test("gameUnitCrashLooping fires once the unit has restarted enough times DURING the wait", () => {
  assert.equal(gameUnitCrashLooping(0, GAME_INSTALL_RESTART_LIMIT), true);
  assert.equal(gameUnitCrashLooping(0, GAME_INSTALL_RESTART_LIMIT + 40), true);
  // The delta is what counts, not the absolute figure: a unit that had already
  // restarted twice before the wait began is judged only on what it does now.
  assert.equal(gameUnitCrashLooping(2, 2 + GAME_INSTALL_RESTART_LIMIT), true);
});

test("gameUnitCrashLooping stays quiet for a healthy or barely-restarted install", () => {
  assert.equal(gameUnitCrashLooping(0, 0), false, "a healthy install never exits, so NRestarts stays 0");
  assert.equal(gameUnitCrashLooping(0, GAME_INSTALL_RESTART_LIMIT - 1), false);
  assert.equal(gameUnitCrashLooping(19, 19), false, "prior restart history alone is not evidence of a loop now");
});

test("gameUnitCrashLooping treats an unknown reading as no evidence, never as a crash", () => {
  // -1 is "no unit, or the guest could not be asked". This check may only ever
  // END a wait early on positive evidence — otherwise it could fail a healthy
  // slow install, which is the exact bug the extended wait exists to prevent.
  assert.equal(gameUnitCrashLooping(-1, 99), false);
  assert.equal(gameUnitCrashLooping(0, -1), false);
  assert.equal(gameUnitCrashLooping(-1, -1), false);
  assert.equal(gameUnitCrashLooping(NaN, 99), false);
});

