/* ------------------------------------------------------------------ *
 * procNetHasPort: the positive evidence the UDP probe cannot get.
 * Guards the 2026-09-07 fix — `udpAttempt` resolves SUCCESS on timeout, so the
 * UDP game-port check passed on silence. A The Forest order was marked DONE
 * and handed over as ready while its container had restarted 118 times and had
 * never started the game at all.
 * ------------------------------------------------------------------ */

// Real shape, captured from a guest on node-2 (7 Days to Die's container).
const UDP_TABLE = `   sl  local_address rem_address   st tx_queue rx_queue tr tm->when retrnsmt   uid  timeout inode ref pointer drops
  425: 00000000:6914 00000000:0000 07 00000000:00000000 00:00000000 00000000  1000        0 45755 2 0000000000000000 0
 2110: 00000000:2AF8 00000000:0000 07 00000000:00000000 00:00000000 00000000  1000        0 46447 2 0000000000000000 0`;

const TCP_TABLE = `  sl  local_address rem_address   st tx_queue rx_queue tr tm->when retrnsmt   uid  timeout inode
   0: 00000000:6914 00000000:0000 0A 00000000:00000000 00:00000000 00000000  1000        0 45001 1 0000000000000000 100 0 0 10 0
   1: 0100007F:1F91 0100007F:C350 01 00000000:00000000 00:00000000 00000000  1000        0 45002 1 0000000000000000 20 4 30 10 -1`;

test("procNetHasPort finds a socket bound to the port", () => {
  assert.equal(procNetHasPort(UDP_TABLE, 26900), true, "0x6914 = 26900");
  assert.equal(procNetHasPort(UDP_TABLE, 11000), true, "0x2AF8 = 11000");
});

test("procNetHasPort does not report a port that is absent", () => {
  // The real Enshrouded case: 15637 was bound, 15636 was not, and the platform
  // was checking 15636.
  assert.equal(procNetHasPort(UDP_TABLE, 15636), false);
  assert.equal(procNetHasPort("", 26900), false, "an empty table proves nothing is bound");
  assert.equal(procNetHasPort(UDP_TABLE, 0), false, "a nonsense port is never 'bound'");
  assert.equal(procNetHasPort(UDP_TABLE, 70000), false);
});

test("procNetHasPort matches on the LOCAL address only, never the remote one", () => {
  // Row 1 of TCP_TABLE has remote port 0xC350 (50000) — an established outbound
  // connection is not the game listening.
  assert.equal(procNetHasPort(TCP_TABLE, 50000, { tcpListeningOnly: true }), false);
  assert.equal(procNetHasPort(TCP_TABLE, 50000), false);
});

test("procNetHasPort requires LISTEN state for TCP but not for UDP", () => {
  // 0x1F91 = 8081, present but in state 01 (ESTABLISHED), not 0A (LISTEN).
  assert.equal(procNetHasPort(TCP_TABLE, 8081, { tcpListeningOnly: true }), false);
  assert.equal(procNetHasPort(TCP_TABLE, 8081), true, "without the TCP rule it is just a bound socket");
  assert.equal(procNetHasPort(TCP_TABLE, 26900, { tcpListeningOnly: true }), true, "0x6914 in state 0A");
});

test("procNetHasPort ignores header lines and blank lines", () => {
  assert.equal(procNetHasPort("sl local_address rem_address st\n\n   \n", 26900), false);
});

