input.new_string:
test("procNetHasPort ignores header lines and blank lines", () => {
  assert.equal(procNetHasPort("sl local_address rem_address st\n\n   \n", 26900), false);
});

test("procNetHasPort does not count a socket bound to loopback inside the container", () => {
  // Real row from Soulmask's own namespace: 0100007F:49C8 is 127.0.0.1:18888.
  // Its `-p 18888:18888/tcp` publish is dead — docker-proxy accepts and the
  // backend dial is refused — so counting this as "bound" would have the check
  // agree with a port that is provably unreachable from anywhere.
  const loopbackOnly = `  sl  local_address rem_address   st tx_queue rx_queue tr tm->when retrnsmt   uid  timeout inode
   0: 0100007F:49C8 00000000:0000 0A 00000000:00000000 00:00000000 00000000  1000        0 45001 1 0000000000000000 100 0 0 10 0`;
  assert.equal(procNetHasPort(loopbackOnly, 18888, { tcpListeningOnly: true }), false);
  // The same port on the wildcard address is real.
  assert.equal(procNetHasPort(loopbackOnly.replace("0100007F", "00000000"), 18888, { tcpListeningOnly: true }), true);
  // …and on a specific non-loopback address (10.20.1.106 = 6A01140A).
  assert.equal(procNetHasPort(loopbackOnly.replace("0100007F", "6A01140A"), 18888, { tcpListeningOnly: true }), true);
});

test("procNetHasPort treats IPv6 loopback and IPv4-mapped loopback as unreachable too", () => {
  const row = (addr: string) =>
    `  sl  local_address                         remote_address                        st tx_queue rx_queue\n` +
    `   0: ${addr} 00000000000000000000000000000000:0000 0A 00000000:00000000`;
  assert.equal(procNetHasPort(row("00000000000000000000000001000000:49C8"), 18888, { tcpListeningOnly: true }), false, "::1");
  assert.equal(procNetHasPort(row("0000000000000000FFFF00000100007F:49C8"), 18888, { tcpListeningOnly: true }), false, "::ffff:127.0.0.1");
  assert.equal(procNetHasPort(row("00000000000000000000000000000000:49C8"), 18888, { tcpListeningOnly: true }), true, ":: wildcard is real");
});

test("Soulmask is checked on the port it really exposes, not its loopback admin port", () => {
  // Regression guard for the 2026-09-08 fix. GAME_PORT was 18888/tcp, which the
  // server binds to 127.0.0.1 inside its container — every order failed the
  // check with ECONNREFUSED. udp 8777 (game) and udp 27015 (query) are the ones
  // on 0.0.0.0, confirmed off the running server's own /proc/net.
  assert.deepEqual(GAME_PORT.soulmask, { port: 8777, protocol: "udp" });
  assert.deepEqual(joinPortFor("soulmask"), GAME_PORT.soulmask, "no override — the check port IS the join port");
});

